  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Asciminib has an absolute oral bioavailability of approximately 73% in humans and shares the 3-hydroxypyrrolidine motif and an aromatic amide/urea-like polar linker with the query, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Lemborexant has at least 87% absolute oral bioavailability in healthy subjects and contains fluorophenyl and heteroaromatic amide features analogous to the query, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Trovafloxacin has a mean absolute oral bioavailability of 87.6% in healthy subjects and contains a difluorophenyl-substituted heteroaromatic core, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paliperidone has an absolute oral bioavailability of 28% in healthy volunteers, which is above the 20% threshold and therefore supports high bioavailability, despite being at the lower end.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Lumateperone has an absolute oral bioavailability of approximately 4.4% in humans, the only clearly low-F analogue; its polycyclic amine scaffold and extensive first-pass metabolism are structurally distant from the query, providing weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query has favorable physicochemical properties and is supported by multiple high-bioavailability analogues (asciminib, lemborexant, trovafloxacin, paliperidone) with F >= 20%; the only low-F analogue (lumateperone) is structurally distant. Therefore predict high oral bioavailability.",
  "evidence_gaps": [
    "No close analogues (Morgan similarity ~0.2) with direct absolute F measurements",
    "No experimental data for the exact query molecule",
    "Lumateperone low F is from a structurally distant scaffold and may not transfer",
    "Some records are predictions or formulation-dependent rather than intrinsic bioavailability measurements"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

